## ----fit-model----------------------------------------------------------------
library(hcinfer)

data("PublicSchools2", package = "hcinfer")
df <- PublicSchools2
df$scaled_income <- df$income / 10000

fit    <- lm(expenditure ~ scaled_income + scaled_income:south - 1, data = df)
result <- hcinfer(fit)


## ----scatter, echo=FALSE, fig.cap="Scatter plot and fitted regression lines (constrained to pass through the origin) relating annual K-12 per-pupil spending to per capita income for Southern states and the remaining U.S. states.", fig.alt="Scatter plot of expenditure against scaled per capita income. Points are colored by region. Two fitted regression lines, constrained to pass through the origin, are overlaid: one for Southern states and one for the remaining states. The two lines have similar positive slopes over the range of the data."----
ggplot(df, aes(x = scaled_income, y = expenditure)) +
  geom_point(aes(color = factor(south)), alpha = 0.8, size = 2.2) +
  geom_abline(
    intercept = 0,
    slope = coef(fit)["scaled_income"],
    color = "#2c5f8a",
    linewidth = 0.9
  ) +
  geom_abline(
    intercept = 0,
    slope = coef(fit)["scaled_income"] + coef(fit)["scaled_income:south"],
    color = "#c0392b",
    linewidth = 0.9
  ) +
  scale_color_manual(
    name = "Region",
    values = c(`0` = "#7A8896", `1` = "#c0392b"),
    labels = c("0" = "non-South", "1" = "South")
  ) +
  labs(
    x = "Per capita income (scaled by 10,000 USD)",
    y = "K-12 per-pupil expenditure (USD)"
  ) +
  theme_minimal(base_size = 12) +
  theme(
    legend.position = "bottom",
    panel.grid.minor = element_blank()
  )


## ----confint-tests------------------------------------------------------------
confint(result)
tests(result)[c("term", "std_error", "z_value", "p_value")]


## ----intervals, echo=FALSE, fig.cap="HCbeta confidence intervals for the coefficients of the education-expenditure regression (intercept-free model). The vertical dashed line indicates the null value used in the coefficient-level hypothesis tests.", fig.alt="Forest plot of HCbeta confidence intervals for the two regression coefficients. Each row shows a horizontal interval with a point estimate and a vertical dashed line marking the null value used for the Wald tests."----
plot(result)


## ----leverage-----------------------------------------------------------------
cov_hcbeta <- vcov_hc(fit, type = "hcbeta")
h <- cov_hcbeta$leverage
p <- 2
n <- length(h)

# Mild leverage (> 2p/n and <= 3p/n)
unname(which(h > 2 * p / n & h <= 3 * p / n))

# High leverage (> 3p/n)
unname(which(h > 3 * p / n))


## ----plot-cov, fig.show="hide"------------------------------------------------
plot(cov_hcbeta)


## ----weights, echo=FALSE, fig.cap="Adjustment factors $g_t$ versus leverage values $h_t$ for the education-expenditure regression (intercept-free model with an interaction term). Red points correspond to observations whose leverage exceeds the conventional high-leverage threshold of $3p/n$.", fig.alt="Four-panel scatter plot of adjustment factors against leverage for HC3, HC4, HC4m, and HCbeta. Each panel uses a free vertical scale. A dashed vertical line marks the 3p/n high-leverage threshold. Points beyond the threshold are highlighted in red."----
hc_types <- c("hc3", "hc4", "hc4m", "hcbeta")
weights_plot_df <- do.call(rbind, lapply(hc_types, function(tp) {
  obj <- vcov_hc(fit, type = tp)
  data.frame(
    h_t = unname(obj$leverage),
    g_t = unname(obj$weights),
    method = obj$label
  )
}))
weights_plot_df$method <- factor(
  weights_plot_df$method,
  levels = c("HC3", "HC4", "HC4m", "HCbeta")
)
pp <- 2
nn <- length(cov_hcbeta$leverage)
w_threshold <- 3 * pp / nn

ggplot(weights_plot_df, aes(x = h_t, y = g_t)) +
  geom_vline(
    xintercept = w_threshold,
    linewidth = 0.35,
    linetype = "dashed",
    color = "#c0392b"
  ) +
  geom_point(
    aes(color = h_t > w_threshold),
    size = 2.4,
    alpha = 0.9
  ) +
  facet_wrap(~ method, scales = "free_y") +
  scale_color_manual(
    name = NULL,
    values = c(`FALSE` = "#2c5f8a", `TRUE` = "#c0392b"),
    breaks = c(FALSE, TRUE),
    labels = c("regular leverage", "high leverage")
  ) +
  labs(
    x = expression(h[t]),
    y = expression(g[t])
  ) +
  theme_minimal(base_size = 12) +
  theme(
    legend.position = "bottom",
    panel.grid.minor = element_blank()
  )


## ----comparison, echo=FALSE---------------------------------------------------
hc_all <- c("hc0", "hc1", "hc2", "hc3", "hc4", "hc4m", "hc5", "hc5m", "hcbeta")
hc_labels <- c("HC0", "HC1", "HC2", "HC3", "HC4", "HC4m", "HC5", "HC5m", "HCbeta")

comparison_rows <- lapply(seq_along(hc_all), function(i) {
  tp <- hc_all[i]
  res <- hcinfer(fit, type = tp)
  test_tab <- tests(res)
  ci_tab <- confint(res)
  test_row <- match("scaled_income:south", test_tab$term)
  ci_row <- match("scaled_income:south", ci_tab$term)
  data.frame(
    Estimator = hc_labels[i],
    `Standard error` = sprintf("%.4f", test_tab$std_error[test_row]),
    `p-value` = sprintf("%.4f", test_tab$p_value[test_row]),
    `max g_t` = sprintf("%.4f", max(res$weights)),
    `95% CI` = sprintf(
      "[%.1f, %.1f]",
      ci_tab$conf_low[ci_row],
      ci_tab$conf_high[ci_row]
    ),
    check.names = FALSE
  )
})
comparison_df <- do.call(rbind, comparison_rows)
knitr::kable(
  comparison_df,
  format = if (knitr::is_latex_output()) "latex" else "html",
  booktabs = TRUE,
  caption = "Robust inference for the income-South interaction coefficient in the public school expenditure regression, intercept-free model. The OLS estimate is -322.66, and income is scaled to units of ten thousand U.S. dollars."
)


## ----weights-nodc, echo=FALSE, fig.cap="Adjustment factors $g_t$ plotted against leverage values $h_t$ for the intercept-free model with an interaction term, fitted to the subsample excluding the District of Columbia. Because no observation exceeds the common high-leverage threshold of $3p/n$, the adjustment factors vary more smoothly across the sample, and the plot() method does not highlight any observations in red.", fig.alt="Four-panel scatter plot of adjustment factors against leverage for HC3, HC4, HC4m, and HCbeta fitted on the subsample without the District of Columbia. A dashed vertical line marks the 3p/n threshold; no points are highlighted as high leverage."----
fit_nodc <- lm(
  expenditure ~ scaled_income + scaled_income:south - 1,
  data = df[df$state != "District of Columbia", ]
)
pp_nodc <- 2
nn_nodc <- nobs(fit_nodc)
w_threshold_nodc <- 3 * pp_nodc / nn_nodc

weights_nodc_df <- do.call(rbind, lapply(hc_types, function(tp) {
