## ----gt-comparison, echo=FALSE------------------------------------------------
fit_intercept <- lm(
  expenditure ~ scaled_income + scaled_income:south,
  data = df
)
gt_rows <- lapply(seq_along(hc_all), function(i) {
  tp <- hc_all[i]
  g_noint <- max(vcov_hc(fit, type = tp)$weights)
  g_int <- max(vcov_hc(fit_intercept, type = tp)$weights)
  data.frame(
    Estimator = hc_labels[i],
    `max g_t (no intercept)` = sprintf("%.2f", g_noint),
    `max g_t (with intercept)` = sprintf("%.2f", g_int),
    check.names = FALSE
  )
})
gt_df <- do.call(rbind, gt_rows)
knitr::kable(
  gt_df,
  format = if (knitr::is_latex_output()) "latex" else "html",
  booktabs = TRUE,
  caption = "Maximum adjustment factor $g_t$ for the interaction coefficient under the intercept-free and intercept models. The intercept-free model is $y_t = \\beta_2 x_{t2} + \\beta_3 x_{t2} x_{t3} + e_t$ and the intercept model is $y_t = \\beta_1 + \\beta_2 x_{t2} + \\beta_3 x_{t2} x_{t3} + e_t$. HCbeta maintains stable adjustment factors across the two specifications."
)

